const $ = id => document.getElementById(id);
const OLD_KEY = 'pinkyTransactionsBlankV1';
let STORAGE_KEY = '';
const MONTHS = [
  'Januari','Februari','Maret','April','Mei','Juni',
  'Juli','Agustus','September','Oktober','November','Desember'
];
const fmt = n => new Intl.NumberFormat('id-ID', {
  style: 'currency', currency: 'IDR', maximumFractionDigits: 0
}).format(Number(n) || 0);

let tx = [];
let editId = null;

function monthName(value) {
  return MONTHS[Number(value) - 1] || '';
}
function yearList() {
  const years = [...new Set(tx.map(t => String(t.date || '').slice(0, 4)).filter(y => /^\d{4}$/.test(y)))].sort();
  const current = String(new Date().getFullYear());
  if (!years.includes(current)) years.push(current);
  return years.sort();
}
function fillYearFilters() {
  const years = yearList();
  ['overviewYear', 'filterYear', 'reportYear'].forEach(id => {
    const el = $(id);
    const previous = el.value;
    el.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
    el.value = years.includes(previous) ? previous : String(new Date().getFullYear());
  });
}
function fillMonthFilters() {
  const monthOptions = MONTHS.map((m, i) => `<option value="${String(i + 1).padStart(2, '0')}">${m}</option>`).join('');
  $('overviewMonth').innerHTML = '<option value="all">Semua bulan</option>' + monthOptions;
  $('filterMonth').innerHTML = '<option value="all">Semua bulan</option>' + monthOptions;
}
function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({
    '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'
  })[c]);
}
function inPeriod(item, year, month) {
  const date = String(item.date || '');
  return date.startsWith(year + '-') && (month === 'all' || date.slice(5, 7) === month);
}
function renderDashboard() {
  const year = $('overviewYear').value;
  const month = $('overviewMonth').value;
  const data = tx.filter(t => inPeriod(t, year, month));
  const income = data.filter(t => t.type === 'income').reduce((s,t) => s + Number(t.amount || 0), 0);
  const expense = data.filter(t => t.type === 'expense').reduce((s,t) => s + Number(t.amount || 0), 0);
  const net = income - expense;
  $('totalBalance').textContent = fmt(net);
  $('totalIncome').textContent = fmt(income);
  $('totalExpenses').textContent = fmt(expense);
  $('totalSavings').textContent = fmt(net);

  const totals = {};
  data.filter(t => t.type === 'expense').forEach(t => {
    const label = String(t.name || '').trim() || 'Tanpa keterangan';
    totals[label] = (totals[label] || 0) + Number(t.amount || 0);
  });
  const entries = Object.entries(totals).sort((a,b) => b[1] - a[1]).slice(0, 10);
  const max = entries[0]?.[1] || 1;
  $('categoryChart').innerHTML = entries.length
    ? entries.map(([name, amount]) => `<div class="bar-row"><span>${esc(name)}</span><div class="bar-track"><div class="bar-fill" style="width:${amount/max*100}%"></div></div><strong>${fmt(amount)}</strong></div>`).join('')
    : '<p class="empty-message">Belum ada pengeluaran pada periode ini ♡</p>';
}
const DAYS = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
function dateHeading(value) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ''));
  if (!m) return String(value || 'Tanpa tanggal');
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return `${DAYS[d.getDay()]}, ${Number(m[3])} ${MONTHS[Number(m[2]) - 1]} ${m[1]}`;
}
function renderTransactions() {
  const type = $('filterType').value;
  const year = $('filterYear').value;
  const month = $('filterMonth').value;
  const query = $('searchTransactions').value.toLowerCase().trim();
  const list = [...tx].filter(t => {
    const text = `${t.name || ''} ${t.category || ''} ${t.account || ''}`.toLowerCase();
    return String(t.date || '').startsWith(year + '-') &&
      (month === 'all' || String(t.date).slice(5,7) === month) &&
      (type === 'all' || t.type === type) && text.includes(query);
  }).sort((a,b) => String(b.date).localeCompare(String(a.date)) ||
      String(b.id).localeCompare(String(a.id), undefined, { numeric: true }));
  $('transactionList').innerHTML = list.length
    ? list.map((t, i) => (i === 0 || t.date !== list[i - 1].date ? `<div class="tx-date">${esc(dateHeading(t.date))}</div>` : '') + `<div class="transaction-row">
        <div class="tx-icon">${t.type === 'income' ? '🌷' : '🎀'}</div>
        <div class="tx-detail"><strong>${esc(t.name)}</strong><small>${esc(t.date)} · ${esc(t.category || 'Tanpa kategori')} · ${esc(t.account || 'Tanpa akun')}</small></div>
        <span class="tx-value ${t.type === 'income' ? 'plus' : 'minus'}">${t.type === 'income' ? '+' : '−'}${fmt(t.amount)}</span>
        <button class="edit-button" data-edit="${esc(t.id)}" aria-label="Edit">✎</button>
        <button class="delete-button" data-delete="${esc(t.id)}" aria-label="Hapus">×</button>
      </div>`).join('')
    : '<p class="empty-message">Belum ada transaksi yang cocok ♡</p>';
}
function renderReport() {
  const year = $('reportYear').value;
  const rows = MONTHS.map((name, i) => {
    const month = String(i + 1).padStart(2, '0');
    const data = tx.filter(t => inPeriod(t, year, month));
    const income = data.filter(t => t.type === 'income').reduce((s,t) => s + Number(t.amount || 0), 0);
    const expense = data.filter(t => t.type === 'expense').reduce((s,t) => s + Number(t.amount || 0), 0);
    return `<tr><td>${name}</td><td class="plus">${fmt(income)}</td><td class="minus">${fmt(expense)}</td><td>${fmt(income-expense)}</td></tr>`;
  });
  $('monthlyTable').innerHTML = rows.join('');
}
function renderAccounts() {
  const accounts = {};
  tx.forEach(t => {
    const name = String(t.account || '').trim();
    if (!name) return;
    accounts[name] ||= {income:0, expense:0};
    accounts[name][t.type === 'income' ? 'income' : 'expense'] += Number(t.amount || 0);
  });
  const entries = Object.entries(accounts);
  $('accountCards').innerHTML = entries.length
    ? entries.map(([name, v]) => `<div class="account-card"><strong>🏦 ${esc(name)}</strong><p>Arus bersih</p><b>${fmt(v.income-v.expense)}</b></div>`).join('')
    : '<p class="empty-message">Belum ada catatan akun ♡</p>';
}
function render() {
  renderDashboard();
  renderTransactions();
  renderReport();
  renderAccounts();
}
function persist() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tx));
  fillYearFilters();
  render();
}
function resetForm() {
  editId = null;
  $('transactionForm').reset();
  refreshNameOptions('');
  $('transactionDate').value = today();
  $('formHeading').textContent = 'Add a transaction 🎀';
  $('submitButton').textContent = '＋ Simpan transaksi';
  $('cancelEdit').classList.add('hidden');
}
$('transactionForm').addEventListener('submit', event => {
  event.preventDefault();
  const item = {
    id: editId || 'tx-' + Date.now(),
    name: $('transactionName').value.trim(),
    amount: Number($('transactionAmount').value),
    type: $('transactionType').value,
    date: $('transactionDate').value,
    category: $('transactionCategory').value.trim(),
    account: $('transactionAccount').value.trim()
  };
  if (!item.name || !item.date || !Number.isFinite(item.amount) || item.amount <= 0) {
    alert('Isi keterangan, nominal, dan tanggal dengan benar ya ♡');
    return;
  }
  if (editId) tx = tx.map(t => String(t.id) === String(editId) ? item : t);
  else tx.push(item);
  resetForm();
  persist();
});
$('transactionList').addEventListener('click', event => {
  const del = event.target.dataset.delete;
  const edit = event.target.dataset.edit;
  if (del) {
    if (confirm('Hapus transaksi ini?')) {
      tx = tx.filter(t => String(t.id) !== String(del));
      persist();
    }
  }
  if (edit) {
    const item = tx.find(t => String(t.id) === String(edit));
    if (!item) return;
    editId = item.id;
    $('transactionAmount').value = item.amount || '';
    $('transactionType').value = item.type || 'expense';
    refreshNameOptions(item.name || '', item.name || '');
    $('transactionDate').value = item.date || today();
    $('transactionCategory').value = item.category || '';
    $('transactionAccount').value = item.account || '';
    $('formHeading').textContent = 'Edit transaction ✎';
    $('submitButton').textContent = 'Simpan perubahan';
    $('cancelEdit').classList.remove('hidden');
    showView('transactions');
  }
});
$('cancelEdit').addEventListener('click', resetForm);
['overviewYear','overviewMonth','reportYear'].forEach(id => $(id).addEventListener('change', render));
['filterType','filterYear','filterMonth'].forEach(id => $(id).addEventListener('change', renderTransactions));
$('searchTransactions').addEventListener('input', renderTransactions);
function today() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

/* ===== Nama & navigasi ===== */
const NAME_KEY = 'gigiName';
const store = {
  get: k => { try { return localStorage.getItem(k); } catch (_) { return null; } },
  set: (k, v) => { try { localStorage.setItem(k, v); } catch (_) {} }
};
function loadTx() {
  try { const s = JSON.parse(store.get(STORAGE_KEY) || '[]'); tx = Array.isArray(s) ? s : []; }
  catch (_) { tx = []; }
}
function showView(v) {
  document.querySelectorAll('.view').forEach(e => e.classList.toggle('active', e.id === v));
  document.querySelectorAll('[data-view]').forEach(a => a.classList.toggle('active', a.dataset.view === v));
  window.scrollTo({ top: 0 });
}
function enterApp(name) {
  store.set(NAME_KEY, name);
  STORAGE_KEY = OLD_KEY;
  loadTx();
  loadNameOptions();
  $('authScreen').classList.add('hidden');
  $('app').classList.remove('hidden');
  document.querySelectorAll('.user-name').forEach(e => e.textContent = name);
  fillYearFilters(); resetForm(); render(); showView('dashboard');
}
function changeName() {
  $('app').classList.add('hidden');
  $('authScreen').classList.remove('hidden');
  $('nameInput').value = store.get(NAME_KEY) || '';
  $('nameInput').focus();
}
function initAuth() {
  document.querySelectorAll('[data-view]').forEach(a => a.addEventListener('click', e => { e.preventDefault(); showView(a.dataset.view); }));
  $('logoutButton').addEventListener('click', changeName);
  $('nameForm').addEventListener('submit', e => {
    e.preventDefault();
    const name = $('nameInput').value.trim();
    if (!name) { $('authMessage').textContent = 'Tulis namamu dulu ya ♡'; return; }
    enterApp(name);
  });
  const saved = store.get(NAME_KEY);
  if (saved) enterApp(saved);
}

/* ===== Pilihan keterangan transaksi (diatur sendiri) ===== */
const NAME_OPT_KEY = 'gigiNameOptionsV1';
let nameOptions = { expense: [], income: [] };

function cleanOptionList(list) {
  const out = [];
  (Array.isArray(list) ? list : []).forEach(v => {
    const n = String(v || '').trim().slice(0, 40);
    if (n && !out.some(x => x.toLowerCase() === n.toLowerCase())) out.push(n);
  });
  return out;
}
function saveNameOptions() {
  store.set(NAME_OPT_KEY, JSON.stringify(nameOptions));
}
function loadNameOptions() {
  let saved = null;
  try { saved = JSON.parse(store.get(NAME_OPT_KEY)); } catch (_) {}
  if (saved && typeof saved === 'object') {
    nameOptions = { expense: cleanOptionList(saved.expense), income: cleanOptionList(saved.income) };
  } else {
    /* pertama kali: ambil dari keterangan transaksi yang sudah ada */
    nameOptions = {
      expense: cleanOptionList(tx.filter(t => t.type !== 'income').map(t => t.name)),
      income: cleanOptionList(tx.filter(t => t.type === 'income').map(t => t.name))
    };
    saveNameOptions();
  }
  renderOptionChips();
  setOptionsPanel(!nameOptions.expense.length && !nameOptions.income.length);
}
function renderOptionChips() {
  ['expense', 'income'].forEach(type => {
    $('chips-' + type).innerHTML = nameOptions[type].length
      ? nameOptions[type].map((n, i) => `<span class="chip">${esc(n)}<button type="button" data-type="${type}" data-index="${i}" aria-label="Hapus ${esc(n)}">×</button></span>`).join('')
      : '<span class="empty-message">Belum ada pilihan ♡</span>';
  });
}
function refreshNameOptions(selected = '', extra = '') {
  const type = $('transactionType').value === 'income' ? 'income' : 'expense';
  const names = [...nameOptions[type]];
  if (extra && !names.includes(extra)) names.push(extra);
  const placeholder = names.length ? 'Pilih keterangan…' : 'Belum ada pilihan — tambah dulu ♡';
  $('transactionName').innerHTML = `<option value="" selected disabled>${placeholder}</option>` +
    names.map(n => `<option value="${esc(n)}">${esc(n)}</option>`).join('');
  $('transactionName').value = names.includes(selected) ? selected : '';
}
function afterOptionsChange() {
  const current = $('transactionName').value;
  renderOptionChips();
  refreshNameOptions(current, editId ? current : '');
}
function setOptionsPanel(open) {
  $('optionsPanel').classList.toggle('hidden', !open);
  $('toggleOptions').setAttribute('aria-expanded', String(open));
  $('toggleOptions').textContent = open ? '✕ Tutup pengaturan' : '⚙ Atur pilihan keterangan';
}
function addNameOption(type) {
  const input = $('newOpt-' + type);
  const value = input.value.trim().slice(0, 40);
  if (!value) { input.focus(); return; }
  if (!nameOptions[type].some(n => n.toLowerCase() === value.toLowerCase())) {
    nameOptions[type].push(value);
    saveNameOptions();
    afterOptionsChange();
  }
  input.value = '';
  input.focus();
}
$('transactionType').addEventListener('change', () => refreshNameOptions(''));
$('toggleOptions').addEventListener('click', () => setOptionsPanel($('optionsPanel').classList.contains('hidden')));
document.querySelectorAll('.add-opt').forEach(b => b.addEventListener('click', () => addNameOption(b.dataset.add)));
['expense', 'income'].forEach(type => $('newOpt-' + type).addEventListener('keydown', e => {
  if (e.key === 'Enter') { e.preventDefault(); addNameOption(type); }
}));
$('optionsPanel').addEventListener('click', e => {
  const btn = e.target.closest('button[data-index]');
  if (!btn) return;
  nameOptions[btn.dataset.type].splice(Number(btn.dataset.index), 1);
  saveNameOptions();
  afterOptionsChange();
});

fillMonthFilters();
initAuth();

/* Gambar jerapah tertanam langsung, tidak perlu file jerapah.png */
const GIRAFFE_SRC = 'data:image/png;base64,';
document.querySelectorAll('img[data-giraffe]').forEach(img => { img.src = GIRAFFE_SRC; });
